ALTER TABLE guild_continuations ADD COLUMN AuthorityCode INTEGER NOT NULL DEFAULT 0 CHECK(typeof(AuthorityCode)='integer' AND AuthorityCode IN(0,1,2));
ALTER TABLE guild_continuations ADD COLUMN ProducerAgentId TEXT NULL CHECK(ProducerAgentId IS NULL OR (ProducerAgentId=upper(ProducerAgentId) AND length(ProducerAgentId)=36 AND substr(ProducerAgentId,9,1)='-' AND substr(ProducerAgentId,14,1)='-' AND substr(ProducerAgentId,19,1)='-' AND substr(ProducerAgentId,24,1)='-' AND length(replace(ProducerAgentId,'-',''))=32 AND replace(ProducerAgentId,'-','') NOT GLOB '*[^0-9A-F]*' AND ProducerAgentId<>'00000000-0000-0000-0000-000000000000'));
ALTER TABLE guild_continuations ADD COLUMN ProducerRunId TEXT NULL CHECK(ProducerRunId IS NULL OR (ProducerRunId=upper(ProducerRunId) AND length(ProducerRunId)=36 AND substr(ProducerRunId,9,1)='-' AND substr(ProducerRunId,14,1)='-' AND substr(ProducerRunId,19,1)='-' AND substr(ProducerRunId,24,1)='-' AND length(replace(ProducerRunId,'-',''))=32 AND replace(ProducerRunId,'-','') NOT GLOB '*[^0-9A-F]*' AND ProducerRunId<>'00000000-0000-0000-0000-000000000000'));
ALTER TABLE guild_continuations ADD COLUMN ProducerQuestId TEXT NULL CHECK(ProducerQuestId IS NULL OR (ProducerQuestId=upper(ProducerQuestId) AND length(ProducerQuestId)=36 AND substr(ProducerQuestId,9,1)='-' AND substr(ProducerQuestId,14,1)='-' AND substr(ProducerQuestId,19,1)='-' AND substr(ProducerQuestId,24,1)='-' AND length(replace(ProducerQuestId,'-',''))=32 AND replace(ProducerQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND ProducerQuestId<>'00000000-0000-0000-0000-000000000000'));
ALTER TABLE guild_continuations ADD COLUMN OperatorPrincipalId TEXT NULL CHECK(OperatorPrincipalId IS NULL OR (OperatorPrincipalId=upper(OperatorPrincipalId) AND length(OperatorPrincipalId)=36 AND substr(OperatorPrincipalId,9,1)='-' AND substr(OperatorPrincipalId,14,1)='-' AND substr(OperatorPrincipalId,19,1)='-' AND substr(OperatorPrincipalId,24,1)='-' AND length(replace(OperatorPrincipalId,'-',''))=32 AND replace(OperatorPrincipalId,'-','') NOT GLOB '*[^0-9A-F]*' AND OperatorPrincipalId<>'00000000-0000-0000-0000-000000000000')) CHECK((AuthorityCode=0 AND ProducerAgentId IS NULL AND ProducerRunId IS NULL AND ProducerQuestId IS NULL AND OperatorPrincipalId IS NULL) OR (AuthorityCode=1 AND ProducerAgentId IS NULL AND ProducerRunId IS NULL AND ProducerQuestId IS NULL AND OperatorPrincipalId IS NOT NULL) OR (AuthorityCode=2 AND ProducerAgentId IS NOT NULL AND ProducerRunId IS NOT NULL AND ProducerQuestId IS NOT NULL AND OperatorPrincipalId IS NULL));
